window.addEventListener("load",()=>{console.log("Theme script loaded"),setTheme(window.matchMedia("(prefers-color-scheme: dark)").matches),document.getElementById("colorscheme-changer")?.addEventListener("click",()=>{setTheme(!document.body.classList.contains("dark"))})});let setTheme=e=>{let t=e?"dark":"light",d=e?"light":"dark";document.querySelectorAll("."+d).forEach(e=>{e.classList.remove(d),e.classList.add(t)})};